local cases={};local function case(n,f)local ok,e=pcall(f);cases[#cases+1]={name=n,passed=ok,message=ok and"ok"or tostring(e)}end;local function eq(a,b)if a~=b then error(tostring(a).." ~= "..tostring(b),2)end end
local A=load_submission("lua/rhenium_prop_alignment/alignment.lua")
local function p(x,y,z)return{x=x,y=y,z=z}end
local function fresh(state)return assert(A.new({max_operations=2,state=state}))end
local stage_sequence=0
local function stage(a,id,e,rev,shift)
 shift=shift or 0;local rows={{"source","origin",p(0,0,0)},{"source","x",p(10,0,0)},{"source","y",p(0,10,0)},{"target","origin",p(shift+100,20,30)},{"target","x",p(shift+100,30,30)},{"target","y",p(shift+90,20,30)}}
 stage_sequence=stage_sequence+1;for i,r in ipairs(rows)do local ok,c=a:stage("s"..stage_sequence..id..i,id,e,rev,r[1],r[2],r[3]);assert(ok,c)end
end
case("six anchors must follow the public stage order",function()local a=fresh();local ok,c=a:stage("x","A","e",1,"source","x",p(1,0,0));assert(not ok);eq(c,"bad_stage_order");stage(a,"A","e",1)end)
case("three point frames map origin axes and probe",function()local a=fresh();stage(a,"A","e",1);local ok,c,d=a:solve("go","A","e",1,p(4,7,3));assert(ok,c);eq(d.position.x,93);eq(d.position.y,24);eq(d.position.z,33)end)
case("collinear and zero length frames are rejected",function()local a=fresh();assert(a:stage("a","A","e",1,"source","origin",p(0,0,0)));local ok,c=a:stage("b","A","e",1,"source","x",p(1,0,0));assert(ok);ok,c=a:stage("c","A","e",1,"source","y",p(2,0,0));assert(not ok);eq(c,"collinear_frame")end)
case("canonical output is quantized and detached",function()local a=fresh();stage(a,"A","e",1);local _,_,d=a:solve("go","A","e",1,p(1/3,2/3,0));local x=d.position.x;d.position.x=9;local s=a:save();assert(x~=9 and s.schema_version==1)end)
case("player entity and revision bind one staging session",function()local a=fresh();assert(a:stage("a","A","e",1,"source","origin",p(0,0,0)));local ok,c=a:stage("b","B","e",1,"source","x",p(1,0,0));assert(not ok);ok,c=a:stage("c","A","e",2,"source","x",p(1,0,0));assert(not ok);eq(c,"stage_identity_mismatch")end)
case("exact request replay is idempotent and conflicts fail",function()local a=fresh();local ok,c,d=a:stage("r","A","e",1,"source","origin",p(0,0,0));assert(ok);d.stage=99;ok,c,d=a:stage("r","A","e",1,"source","origin",p(0,0,0));assert(ok);eq(d.stage,1);ok,c=a:stage("r","A","e",1,"source","x",p(1,0,0));assert(not ok);eq(c,"request_conflict")end)
case("solve requires a complete current generation",function()local a=fresh();local ok,c=a:solve("go","A","e",1,p(0,0,0));assert(not ok);eq(c,"incomplete_stage");stage(a,"A","e",1);ok,c=a:solve("go2","A","e",2,p(0,0,0));assert(not ok)end)
case("operation budget is consumed once per solve",function()local a=fresh();stage(a,"A","e",1);assert(a:solve("g1","A","e",1,p(0,0,0)));assert(a:solve("g1","A","e",1,p(0,0,0)));stage(a,"A","e",1,1);assert(a:solve("g2","A","e",1,p(0,0,0)));stage(a,"A","e",1,2);local ok,c=a:solve("g3","A","e",1,p(0,0,0));assert(not ok);eq(c,"budget_exceeded")end)
case("clear discards only the named player session",function()local a=fresh();assert(a:stage("a","A","e",1,"source","origin",p(0,0,0)));assert(a:stage("b","B","f",1,"source","origin",p(0,0,0)));assert(a:clear("c","A"));local s=a:snapshot();local found=s.sessions.B~=nil;for _,x in ipairs(s.sessions)do found=found or x.player_id=="B"end;assert(found)end)
case("save load preserves stages budget and replay",function()local a=fresh();stage(a,"A","e",1);assert(a:solve("go","A","e",1,p(0,0,0)));local b=fresh(a:save());local ok,c=b:solve("go","A","e",1,p(0,0,0));assert(ok,c);stage(b,"A","e",1);assert(b:solve("go2","A","e",1,p(0,0,0)))end)
case("invalid numbers and identifiers never mutate",function()local a=fresh();local before=a:save();local ok=a:stage("","A","e",1,"source","origin",p(0,0,0));assert(not ok);ok=a:stage("x","A","e",1,"source","origin",p(0/0,0,0));assert(not ok);assert(#(a:snapshot().sessions or{})==#(before.sessions or{}))end)
case("shutdown is idempotent and freezes alignment",function()local a=fresh();assert(a:shutdown());assert(a:shutdown());local ok,c=a:stage("x","A","e",1,"source","origin",p(0,0,0));assert(not ok);eq(c,"shutdown")end)
case("malformed sessions requests and budgets are rejected",function()local a=fresh();stage(a,"A","e",1);assert(a:solve("go","A","e",1,p(0,0,0)));local good=a:save();local variants={};local function add(change)local s=a:save();change(s);variants[#variants+1]=s end;add(function(s)s.sessions="bad"end);add(function(s)s.requests="bad"end);add(function(s)s.spent="bad"end);add(function(s)local k,v=next(s.spent);if k then s.spent[k]=3 else s.spent={A=3}end end);add(function(s)for _,v in pairs(s.requests)do v.ok="yes";return end end);add(function(s)s.sessions={A={entity_id="e",revision=1,source={x=p(1,0,0)},target={}}}end);for _,s in ipairs(variants)do local loaded,code=A.new({max_operations=2,state=s});assert(loaded==nil);eq(code,"invalid_state")end;assert(good.schema_version==1)end)
return{cases=cases}
